function apiWorkflowDescription(provider, workflow) {
  if (workflow === "review") return `Use when asking ${provider.display} direct API to review the current branch diff.`;
  if (workflow === "adversarial-review") return `Use when asking ${provider.display} direct API for an adversarial review.`;
  if (workflow === "custom-review") return `Use when asking ${provider.display} direct API to review explicit files.`;
  if (workflow === "rescue") return `Use when asking ${provider.display} direct API to propose a patch, followed by approved local apply.`;
  if (workflow === "setup") return `Use when checking ${provider.display} direct API reviewer readiness.`;
  throw new Error(`unknown api workflow: ${workflow}`);
}

function apiCommandDescription(provider, workflow) {
  if (workflow === "review") return `Ask ${provider.display} API to review the current branch diff.`;
  if (workflow === "adversarial-review") return `Ask ${provider.display} API to challenge the current branch diff adversarially.`;
  if (workflow === "custom-review") return `Ask ${provider.display} API to review explicit files.`;
  if (workflow === "rescue") return `Ask ${provider.display} API to propose a patch for the current branch diff.`;
  if (workflow === "setup") return `Check ${provider.display} API reviewer readiness.`;
  throw new Error(`unknown api workflow: ${workflow}`);
}

function apiArgumentHint(workflow) {
  if (workflow === "review" || workflow === "adversarial-review") return "\"[--scope-base REF] [review prompt]\"";
  if (workflow === "custom-review") return "\"--scope-paths <files> [review prompt]\"";
  if (workflow === "rescue") return "\"[--scope-base REF] [rescue task]\"";
  if (workflow === "setup") return "\"\"";
  throw new Error(`unknown api workflow: ${workflow}`);
}

function apiPluginName(provider) {
  return `relay-${provider.provider}`;
}

function readApiRelayPluginVersion(provider) {
  const pluginJson = JSON.parse(
    readFileSync(new URL(`../../plugins/${apiPluginName(provider)}/.codex-plugin/plugin.json`, import.meta.url), "utf8"),
  );
  if (typeof pluginJson.version !== "string" || pluginJson.version.trim() === "") {
    throw new Error(`${apiPluginName(provider)}_plugin_version_missing`);
  }
  return pluginJson.version;
}

function apiReviewerScript(provider) {
  return `\${CODEX_HOME:-$HOME/.codex}/plugins/cache/relay-for-codex/${apiPluginName(provider)}/${readApiRelayPluginVersion(provider)}/scripts/api-reviewer.mjs`;
}

function apiReviewerEntrypoint(provider) {
  return `node "${apiReviewerScript(provider)}"`;
}

function apiEntrypointContract(provider) {
  const script = apiReviewerScript(provider);
  const entrypoint = apiReviewerEntrypoint(provider);
  return lines(
    "## Entrypoint Contract",
    `Use the global installed entrypoint \`${entrypoint}\`.`,
    `Do not run bare \`api-reviewer\`, do not rely on \`PATH\`, and do not use repository-relative paths such as \`plugins/${apiPluginName(provider)}/scripts/api-reviewer.mjs\`.`,
    `If \`${script}\` cannot be resolved, stop and report \`api_reviewer_entrypoint_missing\` before any source-bearing command.`,
  );
}

function apiApprovalContract() {
  return lines(
    "## Approval Contract",
    "Direct API reviews send selected source content to an external provider.",
    "Before launching or retrying, render the `approval-request` output and request explicit approval with `recommended_tool_justification`.",
    "If the user has already given explicit current-turn approval for the same provider, mode, source packet, prompt hash, scope resolution, request settings, auth path, billing path, selected route, fallback reason, and approval scope, do not ask again; run `approval-request`, pass its matching `approval_token.value` to `run`, and continue.",
    "`session` approval can be reused only while the full approval tuple is unchanged in the current session.",
    "`once` approval authorizes exactly one matching source send and cannot be replayed.",
    "`approval-grant request` plus `approval-grant activate` creates a short-lived bounded session grant without sending selected source. The operator must pass `--grant-ttl-ms` on request, the max TTL comes from this plugin's `config/session-approval.json`, and activation must reuse the emitted `grant_bounds.expires_at`.",
    "A session grant may authorize later runs without `--approval-token` only when provider, mode, workspace, selected source hashes, prompt hash, scope resolution, request settings, auth path, billing path, selected route, fallback reason, file/byte bounds, schema, fingerprint, and expiry all still match.",
    "Grant-scoped tokens must not be passed to normal `run --approval-token`; normal session or once approval tokens cannot activate grants.",
    "Any change to that tuple requires fresh human approval before source is sent.",
    "Pass `approval_token.value` to `run` with `--approval-token` only after approval.",
    "If approval is denied, follow `denial_action` and generate a relay prompt instead of running the external API command.",
    "Before approval, the runtime should report `source_content_transmission: \"not_sent\"`.",
    "Review timeout defaults to 900000 ms; `API_REVIEWERS_TIMEOUT_MS` is the non-interactive fallback.",
    "Rendered prompts above the provider prompt budget fail before launch with `source_content_transmission: \"not_sent\"`; use narrower scope shards or override `API_REVIEWERS_MAX_PROMPT_CHARS` only after confirming the provider accepts larger prompts.",
  );
}

